    25	async function buildSession(
    26	  repoDir: string,
    27	  dataDir: string,
    28	  reader: ObjectBatchReader,
    29	  record: MetaRecord,
    30	  commits: string[],
    31	): Promise<{ session: Session; redactions: number }> {
    32	  const { ref, meta } = record;
    33	  const cachePath = sessionCachePath(dataDir, repoDir, ref.id, meta.sessionIndex);
    34	  const cached = await readSessionCache(cachePath, meta.transcriptOid);
    35	
    36	  let entries: Session['entries'];
    37	  let redactions: number;
    38	  if (cached) {
    39	    entries = cached.entries;
    40	    redactions = cached.redactions;
    41	  } else {
    42	    const jsonl = await readSessionTranscriptText(repoDir, meta.transcriptOid, reader);
    43	    const parsed = parseTranscript(meta.sessionId, jsonl);
    44	    entries = parsed.entries;
    45	    redactions = parsed.redactions;
    46	    if (meta.transcriptOid) await writeSessionCache(cachePath, { transcriptOid: meta.transcriptOid, entries, redactions });
    47	  }
    48	
    49	  const startedAt = entries[0]?.ts ?? meta.createdAt;
    50	  const endedAt = entries.length > 0 ? entries[entries.length - 1]!.ts : null;
    51	
    52	  return {
    53	    session: {
    54	      id: meta.sessionId,
    55	      checkpointIds: [ref.id],
    56	      agent: meta.agent,
    57	      model: meta.model,
    58	      branch: meta.branch,
    59	      startedAt,
    60	      endedAt,
    61	      turnCount: meta.turnCount,
    62	      tokens: meta.tokens,
    63	      commits,
    64	      filesTouched: meta.filesTouched,
    65	      entries,
    66	    },
    67	    redactions,
    68	  };
    69	}
