    71	/** Reads a repository's Entire checkpoints into normalized sessions for the given window. */
    72	export async function ingest(opts: {
    73	  repoUrl: string;
    74	  dataDir: string;
    75	  since: string;
    76	  until: string;
    77	  maxSessions?: number;
    78	  onProgress?: (message: string) => void;
    79	}): Promise<IngestArtifact> {
    80	  const onProgress = opts.onProgress ?? (() => undefined);
    81	  const maxSessions = opts.maxSessions ?? DEFAULT_MAX_SESSIONS;
    82	
    83	  onProgress('cloning');
    84	  const repoDir = await cloneOrUpdate(opts.repoUrl, opts.dataDir);
    85	  const refs = await listCheckpointRefs(repoDir);
    86	  if (refs.length === 0) throw new NoCheckpointsError(`no checkpoint refs found in ${opts.repoUrl}`);
    87	  onProgress(`read ${refs.length} checkpoints`);
    88	
    89	  const commitMap = await mapCheckpointCommits(repoDir);
    90	  const skipped: { ref: string; reason: string }[] = [];
    91	  const reader = new ObjectBatchReader(repoDir);
    92	
    93	  try {
    94	    const metaRecords: MetaRecord[] = [];
    95	    for (const ref of refs) {
    96	      try {
    97	        const result = await readCheckpointMetadata(repoDir, ref, reader);
    98	        for (const meta of result.sessions) metaRecords.push({ ref, meta });
    99	        skipped.push(...result.skipped);
   100	      } catch (err) {
   101	        skipped.push({ ref: ref.treeish, reason: err instanceof Error ? err.message : String(err) });
   102	      }
   103	    }
   104	
   105	    const survivorIds = selectCandidateSessionIds(
   106	      metaRecords.map((r) => ({ sessionId: r.meta.sessionId, createdAt: r.meta.createdAt })),
   107	      opts.since,
   108	      opts.until,
   109	      maxSessions,
   110	    );
   111	    onProgress(`${survivorIds.size} sessions in window`);
   112	
   113	    const toRead = metaRecords.filter((r) => survivorIds.has(r.meta.sessionId));
   114	    let allSessions: Session[] = [];
   115	    let redactions = 0;
   116	    for (let i = 0; i < toRead.length; i += 1) {
   117	      const record = toRead[i]!;
   118	      onProgress(`parsing ${i + 1}/${toRead.length}`);
   119	      try {
   120	        const commits = commitMap.get(record.ref.id) ?? [];
   121	        const built = await buildSession(repoDir, opts.dataDir, reader, record, commits);
   122	        allSessions.push(built.session);
   123	        redactions += built.redactions;
   124	      } catch (err) {
   125	        skipped.push({
   126	          ref: `${record.ref.treeish}#${record.meta.sessionIndex}`,
   127	          reason: err instanceof Error ? err.message : String(err),
   128	        });
   129	      }
   130	    }
   131	
   132	    const merged = mergeSessions(allSessions);
   133	    const windowed = selectWindow(merged, opts.since, opts.until, maxSessions);
   134	
   135	    const commitShas = Array.from(new Set(windowed.flatMap((s) => s.commits)));
   136	    const cappedCount = Math.min(commitShas.length, MAX_DIFF_COMMITS);
   137	    onProgress(`diffs for ${cappedCount} commits`);
   138	    const { diffs, droppedCount } = await getDiffsBatched(repoDir, commitShas, MAX_DIFF_COMMITS);
   139	    if (droppedCount > 0) skipped.push({ ref: 'diffs', reason: `${droppedCount} commit diff(s) dropped past the ${MAX_DIFF_COMMITS}-commit cap` });
   140	
   141	    const headSha = await git(repoDir, ['rev-parse', 'HEAD']).then((s) => s.trim()).catch(() => '');
   142	
   143	    return {
   144	      repo: { url: opts.repoUrl, dir: repoDir, headSha },
   145	      sessions: windowed,
   146	      diffs,
   147	      skipped,
   148	      enrichments: {},
   149	      redactions,
   150	    };
   151	  } finally {
   152	    reader.close();
   153	  }
   154	}

