    15	const NARRATOR_PREFIX = 'Read as a calm, dry documentary narrator. Pause for a full second between paragraphs.\n\n';
    16	
    17	export async function voiceLines(
    18	  lines: { id: string; text: string }[],
    19	  o: { provider: TtsProvider; voice: string; outDir: string; maxCalls: number },
    20	): Promise<{ mode: 'voiced' | 'captions'; audioPath: string | null; timings: LineTiming[]; calls: number }> {
    21	  if (o.maxCalls <= 0) {
    22	    return { mode: 'captions', audioPath: null, timings: estimateTimings(lines), calls: 0 };
    23	  }
    24	
    25	  const joinedText = NARRATOR_PREFIX + lines.map((l) => l.text).join('\n\n');
    26	  const hash = createHash('sha256').update(`${o.provider.name}\n${o.voice}\n${joinedText}`).digest('hex');
    27	  const cachePath = join(o.outDir, 'cache', `${hash}.wav`);
    28	  const audioPath = join(o.outDir, 'narration.wav');
    29	
    30	  let calls = 0;
    31	  if (existsSync(cachePath)) {
    32	    mkdirSync(dirname(audioPath), { recursive: true });
    33	    copyFileSync(cachePath, audioPath);
    34	  } else {
    35	    let pcm: Buffer;
    36	    let sampleRate: number;
    37	    try {
    38	      const synthesized = await o.provider.synthesize(joinedText, o.voice);
    39	      pcm = synthesized.pcm;
    40	      sampleRate = synthesized.sampleRate;
    41	    } catch (err) {
    42	      if (err instanceof TtsQuotaError) {
    43	        return { mode: 'captions', audioPath: null, timings: estimateTimings(lines), calls: 0 };
    44	      }
    45	      throw err;
    46	    }
    47	    calls = 1;
    48	    writeWav(cachePath, pcm, sampleRate);
    49	    writeWav(audioPath, pcm, sampleRate);
    50	  }
    51	
    52	  const durationSec = readWavDurationSec(audioPath);
    53	  const silences = await detectSilences(audioPath);
    54	  const timings = alignLines(lines, durationSec, silences);
    55	  return { mode: 'voiced', audioPath, timings, calls };
    56	}
    57	
    58	function readWavDurationSec(path: string): number {
    59	  const buf = readFileSync(path);
    60	  const sampleRate = buf.readUInt32LE(24);
    61	  const dataSize = buf.readUInt32LE(40);
    62	  return dataSize / (sampleRate * 2);
    63	}

