    23	/**
    24	 * The stage, with whatever it adds to the meter recorded against the run. A failed attempt is recorded too:
    25	 * the money is spent whether or not the stage returns.
    26	 */
    27	export function recordSpend<T>(deps: Pick<StageDeps, 'db' | 'meter'>, stage: Stage<T>): Stage<T> {
    28	  return {
    29	    ...stage,
    30	    async run(ctx) {
    31	      const before = deps.meter.total();
    32	      try {
    33	        return await stage.run(ctx);
    34	      } finally {
    35	        const spent = deps.meter.total() - before;
    36	        if (spent > 0) addCost(deps.db, ctx.run.id, spent);
    37	      }
    38	    },
    39	  };
    40	}
