    42	/** ingest, edit, verify, script, ground, voice, render, gate. The review stage is built apart and goes before the gate. */
    43	export function buildStages(deps: StageDeps): Stage[] {
    44	  const stages: Stage[] = [ingestStage(), editStage(deps), verifyStage(deps), scriptStage(deps), groundStage(deps), voiceStage(deps), renderStage(), gateStage(deps)];
    45	  return stages.map((stage) => recordSpend(deps, stage));
    46	}

