     5	const NO_SESSIONS = 'no agent sessions found in this window';
     6	
     7	const ERROR_KEEP_CHARS = 1000;
     8	// "git" as a user name is no secret, and replacing it would take every "git" out of git's own message.
     9	const MIN_CREDENTIAL_CHARS = 4;
    10	// The authority the way git reads it: the userinfo runs to the last "@" before the first "/", whatever it holds.
    11	const USERINFO = /(\b[a-z][a-z0-9+.-]{0,31}:\/\/)[^\s/]*@/gi;
    12	const OWN_USERINFO = /^[a-z][a-z0-9+.-]{0,31}:\/\/([^\s/]*)@/i;
    13	
    14	/** The user name and password in a repository URL, as written and percent-decoded, longest first. */
    15	function credentialsOf(repoUrl: string): string[] {
    16	  const userinfo = OWN_USERINFO.exec(repoUrl)?.[1];
    17	  if (userinfo === undefined) return [];
    18	  const colon = userinfo.indexOf(':');
    19	  const parts = colon === -1 ? [userinfo] : [userinfo.slice(0, colon), userinfo.slice(colon + 1)];
    20	  const decoded = parts.map((part) => {
    21	    try {
    22	      return decodeURIComponent(part);
    23	    } catch {
    24	      return part;
    25	    }
    26	  });
    27	  return [...new Set([...parts, ...decoded])].filter((part) => part.length >= MIN_CREDENTIAL_CHARS).sort((a, b) => b.length - a.length);
    28	}
    29	
    30	/**
    31	 * `text` without the given credentials, without the userinfo of any URL in it, and without anything else the
    32	 * redactor knows. A token pasted into the repository URL comes back in git's error messages, and the runner
    33	 * stores those with the run.
    34	 */
    35	function scrub(text: string, credentials: string[]): string {
    36	  const literal = credentials.reduce((t, credential) => t.split(credential).join('[REDACTED]'), text);
    37	  return redact(literal.replace(USERINFO, '$1')).text;
    38	}
    39	
    40	/**
    41	 * The start and the end of an error message, scrubbed. git can fill a 64 MB buffer; a run record holds 2000
    42	 * characters of it. The cut comes first and takes the word it lands in with it, so nothing is scrubbed in part
    43	 * and nothing from beyond the cut can slide into what is kept.
    44	 */
    45	function scrubbedError(message: string, credentials: string[]): string {
    46	  if (message.length <= 2 * ERROR_KEEP_CHARS) return scrub(message, credentials);
    47	  const head = message.slice(0, ERROR_KEEP_CHARS).replace(/\S+$/, '');
    48	  const tail = message.slice(-ERROR_KEEP_CHARS).replace(/^\S+/, '');
    49	  return scrub(`${head} … ${tail}`, credentials);
    50	}
    51	
    52	export function ingestStage(): Stage<IngestArtifact> {
    53	  return {
    54	    name: 'ingest',
    55	    maxAttempts: 2,
    56	    async run(ctx) {
    57	      const { repoUrl, since, until } = ctx.run;
    58	      const credentials = credentialsOf(repoUrl);
    59	      let found: IngestArtifact;
    60	      try {
    61	        found = await ingest({ repoUrl, dataDir: ctx.dataDir, since, until });
    62	      } catch (err) {
    63	        if (!(err instanceof NoCheckpointsError)) throw new Error(scrubbedError(err instanceof Error ? err.message : String(err), credentials));
    64	        found = { repo: { url: repoUrl, dir: '', headSha: '' }, sessions: [], diffs: {}, skipped: [], enrichments: {}, redactions: 0 };
    65	      }
    66	      const artifact: IngestArtifact = {
    67	        ...found,
    68	        // `dir` too: ingest names the clone after the URL, and a one-part path puts the end of the userinfo into
    69	        // that name. Whatever stands before the last "@" of the name is dropped, only for a URL that has userinfo.
    70	        repo: {
    71	          ...found.repo,
    72	          url: scrub(found.repo.url, credentials),
    73	          dir: scrub(OWN_USERINFO.test(repoUrl) ? found.repo.dir.replace(/[^/]*@(?=[^/]*$)/, '') : found.repo.dir, credentials),
    74	        },
    75	        skipped: found.skipped.map((skip) => ({ ...skip, reason: scrubbedError(skip.reason, credentials) })),
    76	      };
    77	
    78	      // Nothing to tell: the run ends here, before any model is asked and before anything is rendered.
    79	      if (artifact.sessions.length === 0) return { artifact, final: { status: 'blocked', reason: NO_SESSIONS } };
    80	
    81	      const count = artifact.sessions.length;
    82	      ctx.log(`${count} session${count === 1 ? '' : 's'}, ${Object.keys(artifact.diffs).length} file diffs, ${artifact.redactions} redactions, ${artifact.skipped.length} checkpoints skipped`);
    83	      return { artifact };
    84	    },
    85	  };
    86	}
