    33	  fetchImpl: typeof fetch,
    34	  model: string,
    35	  key: string,
    36	  text: string,
    37	  voice: string,
    38	): Promise<{ pcm: Buffer; sampleRate: number } | null> {
    39	  const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`;
    40	  const body = JSON.stringify({
    41	    contents: [{ parts: [{ text }] }],
    42	    generationConfig: {
    43	      responseModalities: ['AUDIO'],
    44	      speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: voice } } },
    45	    },
    46	  });
    47	
    48	  for (let attempt = 0; ; attempt++) {
    49	    const res = await fetchImpl(url, {
    50	      method: 'POST',
    51	      headers: { 'x-goog-api-key': key, 'content-type': 'application/json' },
    52	      body,
