 28	/**
 29	 * Whether every reference of a line points at something in the record, and every quote is found where it points.
 30	 * This is the whole check for a flag line. Its words are a literal quote and a fixed sentence, so the style lint
 31	 * does not apply, and the number check could only fail it for the wrong reason: a quote such as "v2" or "22.1.0"
 32	 * holds digits that check does not find in the very entry the quote was taken from.
 33	 */
 34	export function evidenceResolves(line: Line, record: LineContext): { ok: boolean; reasons: string[] } {
 35	  return checked({ ...line, text: '-' }, record, { skipStyle: true });
 36	}
 37	
 38	/**
 39	 * `checkLine`, with each reason as one bounded line. A reason names the reference that failed, in the words a
 40	 * model chose for it, and it travels on: into the rewrite prompt, the loop-back feedback and the run record.
 41	 */
 42	export function checked(line: Line, record: LineContext, o: { skipStyle?: boolean } = {}): { ok: boolean; reasons: string[] } {
 43	  const result = checkLine(line, record, o);
 44	  return { ok: result.ok, reasons: result.reasons.map((reason) => oneLine(reason, ONE_REASON_CHARS)) };
 45	}
