 47	/** `text` in at most `max` characters, around `quote` when the quote is in it. */
 48	function excerpt(text: string, quote: string | undefined, max: number): string {
 49	  if (text.length <= max) return text;
 50	  const at = quote ? text.indexOf(quote) : -1;
 51	  if (at === -1) return cut(text, max);
 52	  const start = Math.max(0, Math.min(at - Math.floor((max - quote!.length) / 2), text.length - max));
 53	  return `${start > 0 ? '…' : ''}${text.slice(start, start + max)}${start + max < text.length ? '…' : ''}`;
 54	}
