 56	/** A reference with the text it resolves to, for a model to read. */
 57	function evidenceText(ref: EvidenceRef, record: LineContext): string {
 58	  if (ref.type === 'stat') {
 59	    return Object.hasOwn(record.facts, ref.key) ? `stat ${ref.key} = ${record.facts[ref.key]}` : `${JSON.stringify(ref)}\n(does not resolve)`;
 60	  }
 61	  const text = ref.type === 'entry' ? record.sessions.flatMap((s) => s.entries).find((e) => e.id === ref.entryId)?.text : record.diffs[`${ref.sha}:${ref.path}`];
 62	  return `${JSON.stringify(ref)}\n${text === undefined ? '(does not resolve)' : recorded(excerpt(text, ref.quote, EVIDENCE_CHARS))}`;
 63	}
