 65	export function groundStage(deps: StageDeps): Stage<GroundArtifact> {
 66	  return {
 67	    name: 'ground',
 68	    maxAttempts: 3,
 69	    async run(ctx) {
 70	      const { storyboard } = ctx.read<ScriptArtifact>('script');
 71	      const ingest = ctx.read<IngestArtifact>('ingest');
 72	      const record: LineContext = { sessions: ingest.sessions, facts: storyboard.facts, diffs: ingest.diffs };
 73	      const cited = (line: Line) => line.evidence.map((ref) => evidenceText(ref, record));
 74	
 75	      /** Why a line may not be spoken: what the checks in code found, or, when they pass, the entailment judge's no. */
 76	      const failures = async (line: Line): Promise<string[]> => {
 77	        const inCode = checked(line, record);
 78	        if (!inCode.ok) return inCode.reasons;
 79	        const { system, user } = entailPrompt({ line: line.text, evidence: cited(line) });
 80	        const { entailed } = await completeJson({ client: deps.client, role: 'judge', name: 'entailment', system, user, output: Entailment });
 81	        return entailed ? [] : [NOT_ENTAILED];
 82	      };
 83	
 84	      /** The line as it may be spoken, after at most two rewrites; or the reasons it may not. */
 85	      const ground = async (line: Line): Promise<{ line: Line } | { reasons: string[] }> => {
 86	        let current = line;
 87	        let reasons = await failures(current);
 88	        for (let n = 0; reasons.length > 0 && n < MAX_REWRITES; n += 1) {
 89	          const { system, user } = rewritePrompt({ line: current.text, reasons, evidence: cited(current) });
 90	          const reply = await completeJson({ client: deps.client, role: 'writer', name: 'rewriter', system, user, output: Rewrite });
 91	          const rewritten = Line.safeParse({ id: line.id, text: reply.text.trim(), evidence: reply.evidence ?? current.evidence });
 92	          if (rewritten.success) {
 93	            current = rewritten.data;
 94	            reasons = await failures(current);
 95	          } else if (!reasons.includes(INVALID_REWRITE)) reasons = [...reasons, INVALID_REWRITE];
 96	        }
 97	        return reasons.length === 0 ? { line: current } : { reasons };
 98	      };
 99	
100	      const out: { result?: StageResult<GroundArtifact> } = {};
101	      await guard('grounding', async () => {
102	        const dropped: GroundArtifact['dropped'] = [];
103	        const scenes: Scene[] = [];
104	        for (const scene of storyboard.scenes) {
105	          if (scene.type === 'title' || scene.type === 'end') scenes.push(scene);
106	          else if (scene.type === 'flag') {
107	            // Code wrote these lines and no model may touch them. A flag stands whole or not at all:
108	            // the claim without the record, or the record without the claim, would mislead.
109	            const reasons = [...new Set(scene.lines.flatMap((line) => evidenceResolves(line, record).reasons))];
110	            if (reasons.length === 0) scenes.push(scene);
111	            else dropped.push(...scene.lines.map((line) => ({ lineId: line.id, reasons })));
112	          } else {
113	            const lines: Line[] = [];
114	            for (const line of scene.lines) {
115	              const grounded = await ground(line);
116	              if ('line' in grounded) lines.push(grounded.line);
117	              else dropped.push({ lineId: line.id, reasons: grounded.reasons });
118	            }
119	            if (lines.length > 0) scenes.push({ ...scene, lines });
120	          }
121	        }
122	
123	        const spoken = scenes.length - 2;   // all but the title and the end card
124	        const kept = scenes.reduce((n, scene) => n + scene.lines.length, 0);
125	        const artifact: GroundArtifact = { storyboard: Storyboard.parse({ ...storyboard, scenes }), dropped, kept };
126	        const reasons = dropped.map((d) => `${d.lineId}: ${d.reasons.join(', ')}`);
127	        ctx.log(`${kept} lines kept, ${dropped.length} dropped, ${spoken} spoken scenes`);
128	
129	        const pass = spoken >= MIN_SPOKEN_SCENES;
130	        out.result = pass
131	          ? { artifact }
132	          : { artifact, loopBackTo: 'script', reason: cut(`only ${spoken} spoken scene${spoken === 1 ? '' : 's'} survived grounding; dropped ${reasons.join('; ')}`, REASON_CHARS) };
133	        return { pass, reasons };
134	      });
135	      if (!out.result) throw new Error('the grounding guard returned without a result');
136	      return out.result;
137	    },
138	  };
139	}

