 37	/** `cut`, ending on a whole word where there is one to end on. */
 38	function cutAtWord(text: string, max: number): string {
 39	  if (text.length <= max) return text;
 40	  const head = text.slice(0, max - 1);
 41	  const space = head.lastIndexOf(' ');
 42	  return `${(space > max / 2 ? head.slice(0, space) : head).trimEnd()}…`;
 43	}
 44	
 45	/** The last `max` characters, starting on a line where one starts early enough: a run's summary is at its end. */
 46	function tail(text: string, max: number): string {
 47	  const trimmed = text.trimEnd();
 48	  if (trimmed.length <= max) return trimmed;
 49	  const end = trimmed.slice(trimmed.length - (max - 1));
 50	  const lineStart = end.indexOf('\n') + 1;
 51	  return `…${lineStart > 0 && lineStart < end.length / 2 ? end.slice(lineStart) : end}`;
 52	}
 53	
 54	function day(iso: string): string {
 55	  const ms = Date.parse(iso);
 56	  return Number.isNaN(ms) ? cut(flat(iso), 24) : new Date(ms).toISOString().slice(0, 10);
 57	}
