 59	function realityOf(claim: FlaggedClaim): string {
 60	  if (claim.verdict === 'stale') return 'Code was edited after the last passing run.';
 61	  if (claim.kind === 'tests_pass') return 'The last test run before that message had failed.';
 62	  const reason = flat(claim.reason ?? '') || 'the record contradicts this claim';
 63	  return cut(`${reason[0]!.toUpperCase()}${reason.slice(1)}${endsSentence(reason) ? '' : '.'}`, ON_SCREEN.flagReality);
 64	}
