 66	/**
 67	 * The flag scene for a claim a rule found contradicted or stale. Every word of it is the agent's own quote,
 68	 * a fixed sentence, or the rule's reason: no model writes any part of a flag.
 69	 */
 70	export function flagScene(claim: FlaggedClaim): SceneOf<'flag'> {
 71	  const quote = flat(claim.quote);
 72	  const spoken = cutAtWord(quote, SPOKEN_QUOTE_CHARS);
 73	  const reality = realityOf(claim);
 74	  return {
 75	    id: `flag_${claim.id}`,
 76	    type: 'flag',
 77	    claimId: claim.id,
 78	    verdict: claim.verdict,
 79	    quote: cut(quote, ON_SCREEN.flagQuote),
 80	    reality,
 81	    lines: [
 82	      // What the agent wrote rests on the entry that holds the words; what the record shows rests on what the rule found.
 83	      { id: `flag_${claim.id}_quote`, text: `The agent wrote: "${spoken}"${endsSentence(spoken) ? '' : '.'}`, evidence: [{ type: 'entry', entryId: claim.entryId, quote: claim.quote }] },
 84	      { id: `flag_${claim.id}_reality`, text: reality, evidence: claim.evidence },
 85	    ],
 86	  };
 87	}
 88	
 89	const isFlagged = (claim: Claim): claim is FlaggedClaim => (claim.verdict === 'contradicted' || claim.verdict === 'stale') && claim.evidence.length > 0;
 90	
 91	// The writer points and narrates; it supplies none of what a scene shows. Keys other than these are ignored.
 92	const WriterReply = z.object({ scenes: z.array(z.unknown()) });
 93	const WriterLine = z.object({ text: z.string().trim().min(1).max(220), evidence: z.array(EvidenceRef).min(1) });
 94	const rawLines = z.array(z.unknown());
 95	const WriterScene = z.discriminatedUnion('type', [
 96	  z.object({ type: z.literal('prompt'), entryId: z.string(), lines: rawLines }),
 97	  z.object({ type: z.literal('terminal'), steps: z.array(z.object({ entryId: z.string() })).min(1), lines: rawLines }),
 98	  z.object({ type: z.literal('diff'), sha: z.string(), path: z.string(), lines: rawLines }),
 99	  z.object({ type: z.literal('stats'), lines: rawLines }),
100	]);
101	type WriterScene = z.infer<typeof WriterScene>;
102	
103	function typeName(raw: unknown): string {
104	  const type = typeof raw === 'object' && raw !== null && 'type' in raw ? raw.type : undefined;
105	  return typeof type === 'string' ? cut(flat(type), 20) : 'untyped';
106	}
