108	export function scriptStage(deps: StageDeps): Stage<ScriptArtifact> {
109	  return {
110	    name: 'script',
111	    maxAttempts: 3,
112	    async run(ctx) {
113	      const ingest = ctx.read<IngestArtifact>('ingest');
114	      const { beats } = ctx.read<EditArtifact>('edit');
115	      const verify = ctx.read<VerifyArtifact>('verify');
116	
117	      const sessions = new Map(ingest.sessions.map((s) => [s.id, s]));
118	      const entries = new Map(ingest.sessions.flatMap((s) => s.entries.map((e) => [e.id, e] as const)));
119	      const commits = knownCommits(ingest);
120	      const facts = computeFacts(ingest.sessions);
121	      const repo = repoLabel(ctx.run.repoUrl);
122	      const windowLabel = [...new Set([day(ctx.run.since), day(ctx.run.until)])].join(' – ');
123	
124	      const runs = new Map<string, ToolRun[]>();
125	      const runsOf = (session: Session): ToolRun[] => {
126	        if (!runs.has(session.id)) runs.set(session.id, collectRuns(session));
127	        return runs.get(session.id)!;
128	      };
129	
130	      // Newest first: the later session, then the later entry.
131	      const startOf = (claim: Claim) => Date.parse(sessions.get(claim.sessionId)?.startedAt ?? '') || 0;
132	      const indexOf = (claim: Claim) => entries.get(claim.entryId)?.index ?? -1;
133	      const flagged = verify.claims
134	        .filter(isFlagged)
135	        .sort((a, b) => startOf(b) - startOf(a) || indexOf(b) - indexOf(a))
136	        .slice(0, MAX_FLAGS);
137	
138	      /** A shell call the record holds a readable result for, as a terminal step; null when there is nothing to show. */
139	      const stepFor = (entryId: string): Step | null => {
140	        const entry = entries.get(entryId);
141	        const session = entry && sessions.get(entry.sessionId);
142	        if (!entry || !session || entry.toolUseId === undefined) return null;
143	        const call = entry.kind === 'tool_call' ? entry : session.entries.find((e) => e.kind === 'tool_call' && e.toolUseId === entry.toolUseId);
144	        if (!call || call.command === undefined) return null;
145	        const result = session.entries.find((e) => e.kind === 'tool_result' && e.toolUseId === call.toolUseId);
146	        if (!result) return null;
147	        // A test, build, type-check or lint run gets its mark from the parsed output. One the parser cannot read gets no mark at all.
148	        const run = runsOf(session).find((r) => r.callEntryId === call.id);
149	        if (run?.outcome === 'unknown') return null;
150	        const ok = run ? run.outcome === 'pass' : !(result.isError ?? false);
151	        return { command: cut(flat(call.command), ON_SCREEN.command), output: tail(result.text, ON_SCREEN.output), ok, entryId: call.id };
152	      };
153	
154	      /** The scene the writer pointed at, filled from the record; or the reason there is nothing there to show. */
155	      const frame = (scene: WriterScene, id: string, lines: Line[]): Scene | string => {
156	        if (scene.type === 'prompt') {
157	          const entry = entries.get(scene.entryId);
158	          if (!entry || entry.kind !== 'user' || flat(entry.text) === '') return `${scene.entryId} is not a human prompt`;
159	          return { id, type: 'prompt', lines, quote: cut(flat(entry.text), ON_SCREEN.promptQuote), sessionId: entry.sessionId, entryId: entry.id };
160	        }
161	        if (scene.type === 'terminal') {
162	          const steps = scene.steps.flatMap((s) => stepFor(s.entryId) ?? []).slice(0, ON_SCREEN.steps);
163	          if (steps.length === 0) return 'no step points at a command with a readable result';
164	          return { id, type: 'terminal', lines, steps };
165	        }
166	        if (scene.type === 'diff') {
167	          const sha = resolveCommit(scene.sha, commits);
168	          const patch = sha === null ? undefined : ingest.diffs[`${sha}:${scene.path}`];
169	          const hunkAt = patch?.search(/^@@/m) ?? -1;
170	          if (sha === null || patch === undefined || hunkAt === -1) return 'no patch for that commit and path';
171	          return { id, type: 'diff', lines, sha, path: scene.path, hunk: cut(patch.slice(hunkAt), ON_SCREEN.hunk), ...patchCounts(patch) };
172	        }
173	        const items = STATS.filter(([key]) => Object.hasOwn(facts, key) && !(key === 'duration.minutes' && facts[key] === 0)).map(([key, label]) => ({
174	          label,
175	          value: cut(String(facts[key]), ON_SCREEN.statValue),
176	          statKey: key,
177	        }));
178	        return { id, type: 'stats', lines, items };
179	      };
180	
181	      const { system, user } = writerPrompt({
182	        repo,
183	        window: windowLabel,
184	        targetSec: TARGET_SEC,
185	        facts,
186	        beats: beats.map((beat) => beatMaterial(beat, ingest, sessions)),
187	        verified: verify.claims
188	          .filter((c) => c.verdict === 'verified')
189	          .slice(0, MATERIAL.claims)
190	          .map((c) => ({ kind: c.kind, quote: cut(flat(c.quote), MATERIAL.quoteChars), entryId: c.entryId })),
191	        flagged: flagged.map((c) => ({ quote: cut(flat(c.quote), MATERIAL.quoteChars), sessionId: c.sessionId })),
192	        feedback: ctx.feedback === null ? null : cut(ctx.feedback, MATERIAL.feedbackChars),
193	      });
194	      const reply = await completeJson({ client: deps.client, role: 'writer', name: 'writer', system, user, output: WriterReply });
195	
196	      const discarded: string[] = [];
197	      const written: Scene[] = [];
198	      let lineCount = 0;
199	      reply.scenes.forEach((raw, n) => {
200	        const where = `scene ${n + 1} (${typeName(raw)})`;
201	        const parsed = WriterScene.safeParse(raw);
202	        if (!parsed.success) return void discarded.push(`${where}: not a scene the writer may produce`);
203	        if (parsed.data.type === 'stats' && written.some((s) => s.type === 'stats')) return void discarded.push(`${where}: the reel closes on one stats scene`);
204	
205	        const kept = parsed.data.lines.flatMap((rawLine, k) => {
206	          const line = WriterLine.safeParse(rawLine);
207	          if (!line.success) discarded.push(`${where} line ${k + 1}: no text or no evidence`);
208	          return line.success ? [line.data] : [];
209	        });
210	        if (kept.length === 0) return void discarded.push(`${where}: no line with evidence`);
211	
212	        const scene = frame(parsed.data, `sc_${written.length + 1}`, kept.map((line) => ({ id: `l${(lineCount += 1)}`, ...line })));
213	        if (typeof scene === 'string') return void discarded.push(`${where}: ${scene}`);
214	        written.push(scene);
215	      });
216	      if (written.length === 0) throw new Error(`the writer returned no usable scene (${discarded.length} discarded)`);
217	
218	      // The arc closes on the stats scene. A flag follows the last validation scene of its session, or precedes the stats.
219	      const body = [...written.filter((s) => s.type !== 'stats'), ...written.filter((s) => s.type === 'stats')];
220	      const validations = body.filter((s) => s.type === 'terminal').reverse();
221	      const flags = flagged.map((claim) => ({
222	        scene: flagScene(claim),
223	        anchor: validations.find((s) => s.steps.some((step) => entries.get(step.entryId)?.sessionId === claim.sessionId))?.id,
224	      }));
225	      const loose = flags.filter((f) => f.anchor === undefined).map((f) => f.scene);
226	      const scenes: Scene[] = [{ id: 'title', type: 'title', lines: [], repo, windowLabel, sessionCount: ingest.sessions.length, commitCount: Number(facts['commits.count']) }];
227	      for (const scene of body) {
228	        if (scene.type === 'stats') scenes.push(...loose.splice(0));
229	        scenes.push(scene, ...flags.filter((f) => f.anchor === scene.id).map((f) => f.scene));
230	      }
231	      scenes.push(...loose, { id: 'end', type: 'end', lines: [], repo, verified: verify.counts.verified, flagged: verify.counts.contradicted + verify.counts.stale });
232	
233	      const storyboard = Storyboard.parse({ runId: ctx.run.id, repo, targetSec: TARGET_SEC, facts, scenes });
234	      ctx.log(`${written.length} written scenes, ${flags.length} flag scenes, ${discarded.length} pieces of writer output discarded`);
235	      return { artifact: { storyboard, discarded } };
236	    },
237	  };
238	}
