240	/** What the writer sees of one beat: the prompts, the agent's messages and the shell runs in its ranges, and its patches. */
241	function beatMaterial(beat: Beat, ingest: IngestArtifact, sessions: Map<string, Session>): WriterMaterial['beats'][number] {
242	  const inRanges = beat.entryRanges.flatMap((range) => {
243	    const session = sessions.get(range.sessionId);
244	    if (!session) return [];
245	    const shell = new Set(session.entries.filter((e) => e.kind === 'tool_call' && e.command !== undefined).map((e) => e.toolUseId));
246	    return session.entries
247	      .slice(Math.max(0, range.from), range.to + 1)
248	      .filter((e) => e.kind === 'user' || e.kind === 'assistant' || (e.toolUseId !== undefined && shell.has(e.toolUseId)));
249	  });
250	  const shown = inRanges.length <= MATERIAL.entries ? inRanges : [...inRanges.slice(0, MATERIAL.entriesFromStart), ...inRanges.slice(MATERIAL.entriesFromStart - MATERIAL.entries)];
251	
252	  const view = (e: Entry) => ({
253	    id: e.id,
254	    kind: e.kind,
255	    text: e.kind === 'tool_result' ? tail(e.text, MATERIAL.entryChars) : cut(e.text, MATERIAL.entryChars),
256	    command: e.kind === 'tool_call' && e.command !== undefined ? cut(flat(e.command), ON_SCREEN.command) : undefined,
257	    errored: e.kind === 'tool_result' ? (e.isError ?? false) : undefined,
258	  });
259	  const patches = beat.commits
260	    .flatMap((sha) => Object.entries(ingest.diffs).filter(([key]) => key.startsWith(`${sha}:`)).map(([key, patch]) => ({ sha, path: key.slice(sha.length + 1), patch })))
261	    .slice(0, MATERIAL.patches)
262	    .map((p) => ({ sha: p.sha, path: p.path, ...patchCounts(p.patch), patch: cut(p.patch, MATERIAL.patchChars) }));
263	
264	  return { kind: beat.kind, title: beat.title, summary: beat.summary, entries: shown.map(view), patches };
265	}

