    31	        reasons.push(`unknown entry: ${ref.entryId}`);
    32	        continue;
    33	      }
    34	      if (ref.quote && !quoteMatches(ref.quote, entry.text)) {
    35	        reasons.push(`quote not found in entry ${ref.entryId}`);
    36	      }
