 21	const UNTERMINATED_PRIVATE_KEY_RE = /-----BEGIN [A-Z ]*PRIVATE KEY-----(?![\s\S]*-----END [A-Z ]*PRIVATE KEY-----)[\s\S]*$/;
 22	
 23	/** redact(), plus a defensive catch for a private key left unterminated by a truncation window. */
 24	export function redactBounded(text: string): { text: string; hits: number } {
 25	  const r = redact(text);
 26	  if (!UNTERMINATED_PRIVATE_KEY_RE.test(r.text)) return r;
 27	  return { text: r.text.replace(UNTERMINATED_PRIVATE_KEY_RE, '[REDACTED:private_key]'), hits: r.hits + 1 };
 28	}
 29	
 30	/** Redacts, then truncates to head+tail — redacting first so a secret can't survive by straddling
 31	 * the cut; bounding the pre-redaction window first so redact() never scans an unbounded string. */
 32	function redactAndTruncateOutput(text: string): { text: string; hits: number } {
 33	  if (text.length <= TOOL_OUTPUT_LIMIT) return redactBounded(text);
 34	
 35	  const windowSize = TOOL_OUTPUT_HEAD + SAFETY_MARGIN + TOOL_OUTPUT_TAIL + SAFETY_MARGIN;
 36	  if (text.length <= windowSize) {
 37	    const r = redactBounded(text);
 38	    return { text: `${r.text.slice(0, TOOL_OUTPUT_HEAD)}\n…[truncated]…\n${r.text.slice(-TOOL_OUTPUT_TAIL)}`, hits: r.hits };
 39	  }
 40	
 41	  const headWindow = text.slice(0, TOOL_OUTPUT_HEAD + SAFETY_MARGIN);
 42	  const tailWindow = text.slice(-(TOOL_OUTPUT_TAIL + SAFETY_MARGIN));
 43	  const redactedHead = redactBounded(headWindow);
 44	  const redactedTail = redactBounded(tailWindow);
 45	  return {
 46	    text: `${redactedHead.text.slice(0, TOOL_OUTPUT_HEAD)}\n…[truncated]…\n${redactedTail.text.slice(-TOOL_OUTPUT_TAIL)}`,
 47	    hits: redactedHead.hits + redactedTail.hits,
 48	  };
 49	}
 50	
 51	function redactAndTruncateInput(inputJson: string): { text: string; hits: number } {
 52	  const bounded = inputJson.length <= TOOL_INPUT_LIMIT + SAFETY_MARGIN ? inputJson : inputJson.slice(0, TOOL_INPUT_LIMIT + SAFETY_MARGIN);
 53	  const r = redactBounded(bounded);
 54	  return { text: r.text.slice(0, TOOL_INPUT_LIMIT), hits: r.hits };
 55	}
