 57	interface ToolUseBlock {
 58	  type: 'tool_use';
 59	  id: string;
 60	  name: string;
 61	  input?: Record<string, unknown>;
 62	  result?: { output?: string; status?: string };
 63	}
 64	
 65	interface TextBlock {
 66	  type?: string;
 67	  id?: string;
 68	  text?: string;
 69	}
 70	
 71	type Block = ToolUseBlock | TextBlock;
 72	
 73	interface TranscriptLine {
 74	  type?: string;
 75	  ts?: string;
 76	  content?: Block[];
 77	}
