 79	/** Parses one session's `transcript.jsonl` into typed entries. A malformed line is skipped, not fatal. */
 80	export function parseTranscript(sessionId: string, jsonl: string): { entries: Entry[]; redactions: number } {
 81	  const entries: Entry[] = [];
 82	  let redactions = 0;
 83	  let index = 0;
 84	
 85	  const pushEntry = (partial: Omit<Entry, 'id' | 'sessionId' | 'index'>) => {
 86	    if (entries.length >= MAX_ENTRIES) return;
 87	    entries.push({ id: entryId(sessionId, index), sessionId, index, ...partial });
 88	    index += 1;
 89	  };
 90	
 91	  for (const rawLine of jsonl.split('\n')) {
 92	    if (entries.length >= MAX_ENTRIES) break;
 93	    const line = rawLine.trim();
 94	    if (!line) continue;
 95	
 96	    let msg: TranscriptLine;
 97	    try {
 98	      msg = JSON.parse(line);
 99	    } catch {
100	      continue;
101	    }
102	    if (!msg || typeof msg !== 'object') continue;
103	
104	    const ts: string | null = typeof msg.ts === 'string' ? msg.ts : null;
105	    const content = Array.isArray(msg.content) ? msg.content : [];
106	
107	    if (msg.type === 'user') {
108	      for (const block of content as TextBlock[]) {
109	        if (!block || block.type === 'image') continue;
110	        if (typeof block.text !== 'string') continue;
111	        const r = redact(block.text);
112	        redactions += r.hits;
113	        pushEntry({ ts, kind: 'user', text: r.text });
114	      }
115	    } else if (msg.type === 'assistant') {
116	      for (const block of content) {
117	        if (!block || (block as TextBlock).type === 'image') continue;
118	
119	        if ((block as ToolUseBlock).type === 'tool_use') {
120	          const toolUse = block as ToolUseBlock;
121	          const input = toolUse.input ?? {};
122	          const command = typeof input.command === 'string' ? input.command : undefined;
123	          const filePath = typeof input.file_path === 'string' ? input.file_path : undefined;
124	
125	          const redactedCommand = command !== undefined ? redact(command) : null;
126	          if (redactedCommand) redactions += redactedCommand.hits;
127	
128	          const inputJson = JSON.stringify(input);
129	          const redactedInput = redactAndTruncateInput(inputJson);
130	          redactions += redactedInput.hits;
131	          const text = redactedInput.text;
132	
133	          pushEntry({
134	            ts,
135	            kind: 'tool_call',
136	            text,
137	            toolName: toolUse.name,
138	            toolUseId: toolUse.id,
139	            ...(redactedCommand ? { command: redactedCommand.text } : {}),
140	            ...(filePath !== undefined ? { filePath } : {}),
141	          });
142	
143	          if (toolUse.result) {
144	            const stripped = stripAnsi(toolUse.result.output ?? '');
145	            const redactedOutput = redactAndTruncateOutput(stripped);
146	            redactions += redactedOutput.hits;
147	            const text = redactedOutput.text;
148	            pushEntry({
149	              ts,
150	              kind: 'tool_result',
151	              text,
152	              toolName: toolUse.name,
153	              toolUseId: toolUse.id,
154	              isError: toolUse.result.status !== 'success',
155	            });
156	          }
157	        } else if ((block as TextBlock).type === 'text' && typeof (block as TextBlock).text === 'string') {
158	          const r = redact((block as TextBlock).text!);
159	          redactions += r.hits;
160	          pushEntry({ ts, kind: 'assistant', text: r.text });
161	        }
162	      }
163	    }
164	  }
165	
166	  return { entries, redactions };
167	}

