 24	/** `text` in at most `max` characters; a cut is marked with an ellipsis that counts towards the limit. */
 25	export function cut(text: string, max: number): string {
 26	  return text.length <= max ? text : `${text.slice(0, max - 1)}…`;
 27	}
 28	
 29	/** `text` as one line of at most `max` characters: line breaks and control characters become single spaces. */
 30	export function oneLine(text: string, max: number): string {
 31	  // eslint-disable-next-line no-control-regex
 32	  return cut(text.replace(/[\u0000-\u001f\u007f\u0085\u2028\u2029\s]+/g, ' ').trim(), max);
 33	}
