 75	/** Every commit the artifact knows: the ones linked to a session and the ones it holds a patch for. */
 76	export function knownCommits(ingest: IngestArtifact): string[] {
 77	  const shas = new Set(ingest.sessions.flatMap((s) => s.commits));
 78	  for (const key of Object.keys(ingest.diffs)) shas.add(key.slice(0, key.indexOf(':')));
 79	  return [...shas];
 80	}
