 82	/** The full hash `sha` stands for: itself when known, or the one known commit it is a prefix of. */
 83	export function resolveCommit(sha: string, known: string[]): string | null {
 84	  if (known.includes(sha)) return sha;
 85	  if (sha.length < MIN_SHA_PREFIX) return null;
 86	  const matches = known.filter((k) => k.startsWith(sha));
 87	  return matches.length === 1 ? matches[0]! : null;
 88	}
 89	
 90	const cutOptional = (text: string | undefined, max: number) => (text === undefined ? undefined : cut(text, max));
 91	
 92	// Ingest bounds an entry's text but not its command, file path or tool name, so every string is cut here.
 93	function entryView(e: Entry) {
 94	  return {
 95	    id: e.id,
 96	    index: e.index,
 97	    kind: e.kind,
 98	    text: cut(e.text, ENTRY_TEXT_CHARS),
 99	    toolName: cutOptional(e.toolName, NAME_CHARS),
100	    command: cutOptional(e.command, COMMAND_CHARS),
101	    filePath: cutOptional(e.filePath, PATH_CHARS),
102	    isError: e.isError,
103	  };
104	}
