106	/** The editor's read-only view of the ingest artifact. Every result is bounded, whatever the transcript holds. */
107	export function transcriptTools(ingest: IngestArtifact): Tool[] {
108	  const sessions = new Map(ingest.sessions.map((s) => [s.id, s]));
109	  const commits = knownCommits(ingest);
110	  const sessionOf = (id: string): Session => {
111	    const found = sessions.get(id);
112	    if (!found) throw new Error(`unknown session: ${id}`);
113	    return found;
114	  };
115	  const commitOf = (sha: string): string => {
116	    const found = resolveCommit(sha, commits);
117	    if (!found) throw new Error(`unknown commit: ${sha}`);
118	    return found;
119	  };
120	
121	  return [
122	    defineTool({
123	      name: 'list_sessions',
124	      description: 'List every recorded session in the window: id, agent, model, start, end, entry count, linked commits and the first human prompt.',
125	      parameters: z.object({}),
126	      execute: async () =>
127	        ingest.sessions.map((s) => ({
128	          id: s.id,
129	          agent: cut(s.agent, NAME_CHARS),
130	          model: s.model === null ? null : cut(s.model, NAME_CHARS),
131	          start: s.startedAt,
132	          end: s.endedAt,
133	          entryCount: s.entries.length,
134	          commits: s.commits.slice(0, MAX_LISTED_COMMITS),
135	          firstPrompt: cut(s.entries.find((e) => e.kind === 'user')?.text ?? '', FIRST_PROMPT_CHARS),
136	        })),
137	    }),
138	    defineTool({
139	      name: 'read_entries',
140	      description: `Read the entries of a session from index "from" to index "to", both included. Returns at most ${MAX_ENTRIES_PER_READ} entries per call; "next" is the index to continue from, or null.`,
141	      parameters: z.object({ sessionId: z.string(), from: z.number().int(), to: z.number().int() }),
142	      execute: async ({ sessionId, from, to }) => {
143	        const session = sessionOf(sessionId);
144	        const start = Math.max(0, from);
145	        const end = Math.min(to, session.entries.length - 1);
146	        const entries = session.entries.slice(start, end + 1).slice(0, MAX_ENTRIES_PER_READ);
147	        const next = start + entries.length;
148	        return { entries: entries.map(entryView), entryCount: session.entries.length, next: next <= end ? next : null };
149	      },
150	    }),
151	    defineTool({
152	      name: 'search_transcript',
153	      description: `Find entries whose text or command contains the query, ignoring case, across every session. Returns up to ${MAX_MATCHES} matches with their entry ids.`,
154	      parameters: z.object({ query: z.string().min(1) }),
155	      execute: async ({ query }) => {
156	        const needle = query.toLowerCase();
157	        const matches: { id: string; sessionId: string; index: number; kind: Entry['kind']; snippet: string }[] = [];
158	        let more = false;
159	        for (const entry of ingest.sessions.flatMap((s) => s.entries)) {
160	          const haystack = `${entry.command ?? ''}\n${entry.text}`;
161	          const at = haystack.toLowerCase().indexOf(needle);
162	          if (at === -1) continue;
163	          if (matches.length === MAX_MATCHES) {
164	            more = true;
165	            break;
166	          }
167	          const from = Math.max(0, at - SNIPPET_CHARS / 2);
168	          matches.push({ id: entry.id, sessionId: entry.sessionId, index: entry.index, kind: entry.kind, snippet: haystack.slice(from, from + SNIPPET_CHARS).trim() });
169	        }
170	        return { matches, more };
171	      },
172	    }),
173	    defineTool({
174	      name: 'get_diff',
175	      description: 'List the files a commit changed, with added and removed line counts.',
176	      parameters: z.object({ sha: z.string() }),
177	      execute: async ({ sha }) => {
178	        const prefix = `${commitOf(sha)}:`;
179	        const files = Object.entries(ingest.diffs)
180	          .filter(([key]) => key.startsWith(prefix))
181	          .map(([key, patch]) => ({ path: key.slice(prefix.length), ...patchCounts(patch) }));
182	        return { files };
183	      },
184	    }),
185	    defineTool({
186	      name: 'get_patch',
187	      description: 'Read the patch of one file in one commit.',
188	      parameters: z.object({ sha: z.string(), path: z.string() }),
189	      execute: async ({ sha, path }) => {
190	        const patch = ingest.diffs[`${commitOf(sha)}:${path}`];
191	        if (patch === undefined) throw new Error(`no patch for ${path} in ${sha}`);
192	        return { patch };
193	      },
194	    }),
195	  ];
196	}
