  9	function extractText(content: ChatMessage['content']): string {
 10	  if (typeof content === 'string') return content;
 11	  if (Array.isArray(content)) return content.filter((p) => p.type === 'text').map((p) => p.text).join('\n');
 12	  return '';
 13	}
 14	
 15	// Scans with indexOf rather than a `\s*([\s\S]*?)\s*` regex: that shape backtracks catastrophically
 16	// on long, close-but-not-quite-fenced model output, which is attacker-reachable via prompt injection.
 17	function stripFences(text: string): string {
 18	  const trimmed = text.trim();
 19	  const openIdx = trimmed.indexOf('```');
 20	  if (openIdx === -1) return trimmed;
 21	  const afterLangTag = trimmed.indexOf('\n', openIdx + 3);
 22	  const bodyStart = afterLangTag === -1 ? openIdx + 3 : afterLangTag + 1;
 23	  const closeIdx = trimmed.indexOf('```', bodyStart);
 24	  if (closeIdx === -1) return trimmed;
 25	  return trimmed.slice(bodyStart, closeIdx).trim();
 26	}
 27	
 28	function tryParseJson<T>(message: ChatMessage, schema: z.ZodType<T>): { ok: true; value: T } | { ok: false; error: string } {
 29	  const raw = stripFences(extractText(message.content));
 30	  let json: unknown;
 31	  try {
 32	    json = JSON.parse(raw);
 33	  } catch (err) {
 34	    return { ok: false, error: err instanceof Error ? err.message : String(err) };
 35	  }
 36	  const result = schema.safeParse(json);
 37	  if (result.success) return { ok: true, value: result.data };
 38	  return { ok: false, error: result.error.message };
 39	}
 40	
 41	function repairPrompt(zodError: string): string {
 42	  return `Your last reply was not valid JSON for the required schema. Zod error:\n${zodError}\n\nReply with JSON only, no commentary, no code fences.`;
 43	}
 44	
 45	async function parseOrRepair<T>(
 46	  client: ModelClient,
 47	  role: Role,
 48	  priorMessages: ChatMessage[],
 49	  first: ChatMessage,
 50	  output: z.ZodType<T>,
 51	  name: string,
 52	): Promise<T> {
 53	  const parsed = tryParseJson(first, output);
 54	  if (parsed.ok) return parsed.value;
 55	
 56	  const repairMessages: ChatMessage[] = [...priorMessages, first, { role: 'user', content: repairPrompt(parsed.error) }];
 57	  const second = await client.complete({ role, messages: repairMessages });
 58	  const repaired = tryParseJson(second.message, output);
 59	  if (repaired.ok) return repaired.value;
 60	  throw new ModelOutputError(`${name}: model did not return valid JSON for the expected schema after one repair turn`);
 61	}
