 63	export async function completeJson<T>(o: {
 64	  client: ModelClient;
 65	  role: Role;
 66	  name: string;
 67	  system: string;
 68	  user: string | ContentPart[];
 69	  output: z.ZodType<T>;
 70	}): Promise<T> {
 71	  const messages: ChatMessage[] = [
 72	    { role: 'system', content: o.system },
 73	    { role: 'user', content: o.user },
 74	  ];
 75	  const first = await o.client.complete({ role: o.role, messages });
 76	  return parseOrRepair(o.client, o.role, messages, first.message, o.output, o.name);
 77	}
