 79	export async function runAgent<T>(o: {
 80	  client: ModelClient;
 81	  role: Role;
 82	  name: string;
 83	  system: string;
 84	  user: string;
 85	  tools: Tool[];
 86	  output: z.ZodType<T>;
 87	  maxSteps?: number;
 88	}): Promise<{ output: T; steps: number }> {
 89	  return traced('AGENT', o.name, async () => {
 90	    const maxSteps = o.maxSteps ?? 24;
 91	    const toolByName = new Map(o.tools.map((t) => [t.name, t]));
 92	    const messages: ChatMessage[] = [
 93	      { role: 'system', content: o.system },
 94	      { role: 'user', content: o.user },
 95	    ];
 96	
 97	    for (let step = 1; step <= maxSteps; step++) {
 98	      const completion = await o.client.complete({ role: o.role, messages, tools: o.tools });
 99	      messages.push(completion.message);
100	
101	      const calls = completion.message.tool_calls;
102	      if (!calls || calls.length === 0) {
103	        const output = await parseOrRepair(o.client, o.role, messages.slice(0, -1), completion.message, o.output, o.name);
104	        return { output, steps: step };
105	      }
106	
107	      for (const call of calls) {
108	        const resultText = await traced('TOOL', call.function.name, async () => {
109	          const tool = toolByName.get(call.function.name);
110	          if (!tool) throw new Error(`unknown tool: ${call.function.name}`);
111	          const args = JSON.parse(call.function.arguments);
112	          const parsedArgs = tool.parameters.safeParse(args);
113	          if (!parsedArgs.success) throw new Error(parsedArgs.error.message);
