19	function runEvidence(run: ToolRun): EvidenceRef[] {
20	  const refs: EvidenceRef[] = [entryRef(run.callEntryId)];
21	  if (run.resultEntryId) refs.push(entryRef(run.resultEntryId));
22	  return refs;
