29	// Shared by tests_pass (class ['test']) and build_passes (classes ['build', 'typecheck', 'lint']):
30	// consider the last matching run before the claim's entry, then check for an edit since.
31	function lastRunVerdict(claim: Claim, session: Session, classes: CommandClass[], noRunReason: string): Verdicted {
32	  const claimEntry = findEntry(session, claim.entryId);
33	  if (!claimEntry) return unverifiable('claim entry not found in session');
34	
35	  const runs = collectRuns(session).filter((r) => classes.includes(r.cls) && r.index < claimEntry.index);
36	  if (runs.length === 0) return unverifiable(noRunReason);
37	
38	  const last = runs[runs.length - 1]!;
39	  if (last.outcome === 'fail') return { verdict: 'contradicted', reason: 'the last recorded run failed', evidence: runEvidence(last) };
40	  if (last.outcome === 'unknown') return unverifiable('the last recorded run output was not recognised');
41	
42	  const edit = session.entries.find(
43	    (e) =>
44	      e.kind === 'tool_call' &&
45	      e.index > last.index &&
46	      e.index < claimEntry.index &&
47	      e.toolName !== undefined &&
48	      EDIT_TOOLS.has(e.toolName) &&
49	      e.filePath !== undefined &&
50	      !e.filePath.endsWith('.md')
51	  );
52	  if (edit) {
53	    return {
54	      verdict: 'stale',
55	      reason: 'a source file was edited after the last passing run',
56	      evidence: [entryRef(edit.id), ...runEvidence(last)],
57	    };
58	  }
59	  return { verdict: 'verified', reason: 'the last recorded run passed with no edits after', evidence: runEvidence(last) };
60	}
