62	function ranCommand(claim: Claim, session: Session): Verdicted {
63	  const claimEntry = findEntry(session, claim.entryId);
64	  if (!claimEntry || !claim.subject) return unverifiable('no matching command is recorded before this message');
65	
66	  const subject = normalize(claim.subject);
67	  if (!subject) return unverifiable('no matching command is recorded before this message');
68	  const calls = session.entries.filter(
69	    (e) => e.kind === 'tool_call' && e.index < claimEntry.index && e.command && normalize(e.command).includes(subject)
70	  );
71	  if (calls.length === 0) return unverifiable('no matching command is recorded before this message');
72	
73	  const call = calls[calls.length - 1]!;
74	  const result = session.entries.find((e) => e.kind === 'tool_result' && e.toolUseId === call.toolUseId);
75	  if (!result) return unverifiable('the matching command has no recorded result');
76	
77	  const evidence = [entryRef(call.id), entryRef(result.id)];
78	  if (result.isError) return { verdict: 'contradicted', reason: 'the matching command errored', evidence };
79	  return { verdict: 'verified', reason: 'the matching command succeeded', evidence };
80	}
