82	function fixedError(claim: Claim, session: Session): Verdicted {
83	  const claimEntry = findEntry(session, claim.entryId);
84	  if (!claimEntry || !claim.subject) return unverifiable('no error text is recorded for this claim');
85	
86	  const subject = normalize(claim.subject);
87	  if (!subject) return unverifiable('no error text is recorded for this claim');
88	  const errorResult = session.entries.find(
89	    (e) => e.kind === 'tool_result' && e.index < claimEntry.index && normalize(e.text).includes(subject)
90	  );
91	  if (!errorResult) return unverifiable('the error text is not recorded in any tool result');
92	
93	  const errorCall = session.entries.find((e) => e.kind === 'tool_call' && e.toolUseId === errorResult.toolUseId);
94	  if (!errorCall || !errorCall.command) return unverifiable('the failing command is not recorded');
95	  const cls = classifyCommand(errorCall.command);
96	
97	  const laterCalls = session.entries.filter(
98	    (e) =>
99	      e.kind === 'tool_call' &&
100	      e.index > errorResult.index &&
101	      e.index < claimEntry.index &&
102	      e.command &&
103	      classifyCommand(e.command) === cls
104	  );
105	  if (laterCalls.length === 0) return unverifiable('no later run of the same kind is recorded before this message');
106	
107	  const lastCall = laterCalls[laterCalls.length - 1]!;
108	  const lastResult = session.entries.find((e) => e.kind === 'tool_result' && e.toolUseId === lastCall.toolUseId);
109	  if (!lastResult) return unverifiable('the later run has no recorded result');
110	
111	  const outcome = parseOutcome(cls, lastResult.text, lastResult.isError ?? false);
112	  const stillPresent = normalize(lastResult.text).includes(subject);
113	  const evidence: EvidenceRef[] = [entryRef(errorResult.id), entryRef(lastCall.id), entryRef(lastResult.id)];
114	
115	  if (stillPresent || outcome === 'fail') {
116	    return { verdict: 'contradicted', reason: 'the error is still present in a later run', evidence };
117	  }
118	  if (outcome === 'unknown') return unverifiable('the later run output was not recognised');
119	  return { verdict: 'verified', reason: 'a later run no longer shows the error', evidence };
120	}
