122	export function verifyClaim(claim: Claim, session: Session): Claim {
123	  if (claim.kind === 'implemented') return claim;
124	
125	  const entry = findEntry(session, claim.entryId);
126	  if (!entry || !quoteMatches(claim.quote, entry.text)) {
127	    return { ...claim, verdict: 'unverifiable', reason: 'quote not found in transcript', evidence: [] };
128	  }
129	
130	  let result: Verdicted;
131	  switch (claim.kind) {
132	    case 'tests_pass':
133	      result = lastRunVerdict(claim, session, ['test'], 'no test run is recorded before this message');
134	      break;
135	    case 'build_passes':
136	      result = lastRunVerdict(claim, session, ['build', 'typecheck', 'lint'], 'no build, typecheck or lint run is recorded before this message');
137	      break;
138	    case 'ran_command':
139	      result = ranCommand(claim, session);
140	      break;
141	    case 'fixed_error':
142	      result = fixedError(claim, session);
143	      break;
144	    default:
145	      result = unverifiable('unknown claim kind');
146	  }
147	  return { ...claim, ...result };
148	}
