150	export function verifyClaims(claims: Claim[], sessions: Session[]): Claim[] {
151	  const byId = new Map(sessions.map((s) => [s.id, s]));
152	  return claims.map((c) => {
153	    const session = byId.get(c.sessionId);
154	    if (!session) return { ...c, verdict: 'unverifiable', reason: 'session not found', evidence: [] };
155	    return verifyClaim(c, session);
156	  });
157	}
