 3	export function alignLines(
 4	  lines: { id: string; text: string }[],
 5	  totalSec: number,
 6	  silences: { start: number; end: number }[],
 7	): LineTiming[] {
 8	  const n = lines.length;
 9	  const totalChars = lines.reduce((sum, l) => sum + l.text.length, 0) || 1;
10	  const usable = silences.filter((s) => s.start > 0 && s.end < totalSec);
11	  const used = new Set<number>();
12	  const tolerance = totalSec * 0.25;
13	
14	  const boundaries: number[] = [];
15	  let cumChars = 0;
16	  for (let i = 0; i < n - 1; i++) {
17	    cumChars += lines[i]!.text.length;
18	    const expected = (totalSec * cumChars) / totalChars;
19	
20	    let bestIndex = -1;
21	    let bestDist = Infinity;
22	    for (let j = 0; j < usable.length; j++) {
23	      if (used.has(j)) continue;
24	      const mid = (usable[j]!.start + usable[j]!.end) / 2;
25	      const dist = Math.abs(mid - expected);
26	      if (dist <= tolerance && dist < bestDist) {
27	        bestDist = dist;
28	        bestIndex = j;
29	      }
30	    }
31	
32	    if (bestIndex >= 0) {
33	      used.add(bestIndex);
34	      boundaries.push((usable[bestIndex]!.start + usable[bestIndex]!.end) / 2);
35	    } else {
36	      boundaries.push(expected);
37	    }
38	  }
39	
40	  const timings: LineTiming[] = [];
41	  let start = 0;
42	  for (let i = 0; i < n; i++) {
43	    const end = i < boundaries.length ? boundaries[i]! : totalSec;
44	    timings.push({ lineId: lines[i]!.id, startSec: start, endSec: end });
45	    start = end;
46	  }
47	  return timings;
48	}
49	
50	export function estimateTimings(lines: { id: string; text: string }[]): LineTiming[] {
51	  let start = 0;
52	  return lines.map((l) => {
53	    const duration = Math.max(l.text.length / 15, 1.6);
54	    const end = start + duration;
55	    const timing: LineTiming = { lineId: l.id, startSec: start, endSec: end };
56	    start = end;
57	    return timing;
58	  });
59	}

