36	export function selectCandidateSessionIds(hints: SessionTimeHint[], since: string, until: string, maxSessions: number): Set<string> {
37	  const sinceMs = Date.parse(since);
38	  const untilMs = Date.parse(until);
39	
40	  const byId = new Map<string, { min: number; max: number }>();
41	  for (const hint of hints) {
42	    const ms = Date.parse(hint.createdAt);
43	    const existing = byId.get(hint.sessionId);
44	    if (!existing) byId.set(hint.sessionId, { min: ms, max: ms });
45	    else {
46	      existing.min = Math.min(existing.min, ms);
47	      existing.max = Math.max(existing.max, ms);
48	    }
49	  }
50	
51	  const inWindow = Array.from(byId.entries()).filter(([, r]) => r.min <= untilMs && r.max >= sinceMs);
52	  inWindow.sort((a, b) => b[1].max - a[1].max);
53	
54	  return new Set(inWindow.slice(0, maxSessions).map(([id]) => id));
55	}
56	
57	/** Keeps sessions inside [since, until], sorted newest-first, truncated to maxSessions, then returned chronologically. */
58	export function selectWindow(sessions: Session[], since: string, until: string, maxSessions: number): Session[] {
59	  const sinceMs = Date.parse(since);
60	  const untilMs = Date.parse(until);
61	
62	  const inWindow = sessions.filter((s) => {
63	    const startedMs = Date.parse(s.startedAt);
64	    const endedMs = Date.parse(s.endedAt ?? s.startedAt);
65	    return startedMs <= untilMs && endedMs >= sinceMs;
66	  });
67	
68	  const newestFirst = [...inWindow].sort(
69	    (a, b) => Date.parse(b.endedAt ?? b.startedAt) - Date.parse(a.endedAt ?? a.startedAt),
70	  );
71	
72	  return newestFirst.slice(0, maxSessions).sort((a, b) => Date.parse(a.startedAt) - Date.parse(b.startedAt));
73	}

